// Verbs the text names outside the table.
const OTHER_NAMED_VERBS: readonly string[] = Object.freeze(["commands", "setup"]);

/** Every engine verb SKILL.md names, the table's first and in its order, without repeats. */
export function skillNamedVerbs(): readonly string[] {
  return [...new Set([...SKILL_NAVIGATION.flatMap((entry) => entry.verbs), ...OTHER_NAMED_VERBS])];
}

export interface RenderSkillMarkdownInput {
  // The engine version the file is generated for.
  readonly version: string;
  // The names in that engine's command catalog.
  readonly catalogNames: readonly string[];
}

function navigationRow(entry: SkillNavigationEntry): string {
  return `| ${entry.moment} | ${entry.verbs.map((verb) => `\`${verb}\``).join(", ")} | ${entry.action} |`;
}

/**
 * SKILL.md for one engine version (TCRN-CROSS-STORY-479 R1): the frontmatter (name and the
 * finalized description A), the navigation table and how to run a verb, the three-step routine,
 * and the pointer to references/. Refuses a verb the catalog does not carry, a version that is not
 * a release version, and a result of SKILL_MARKDOWN_BYTE_LIMIT bytes or more.
 */
export function renderSkillMarkdown(input: RenderSkillMarkdownInput): string {
  if (!isEngineVersion(input.version)) {
    fail("SKILL_VERSION_INVALID", `${String(input.version)} is not an engine release version`, { version: String(input.version) });
  }
  const catalog = new Set(input.catalogNames);
  for (const verb of skillNamedVerbs()) {
    if (!catalog.has(verb)) {
      fail("SKILL_NAVIGATION_VERB_UNKNOWN", `${verb} is not a verb of engine ${input.version}; the navigation would name a verb that does not run`, { verb, version: input.version });
    }
  }
  const lines = [
    "---",
    `name: ${BRAND.helper.id}`,
    // A YAML double-quoted scalar: the description holds ": ", which a plain scalar cannot.
    `description: ${JSON.stringify(SKILL_DESCRIPTION)}`,
    "---",
    "",
    `# ${BRAND.helper.name}`,
    "",
    `Navigation for ${BRAND.engine.name} ${input.version}: generated by this engine; do not edit by hand.`,
    "",
    "Execution protocol: tcrn.host-execution-request.v1.",
    "",
    "## Navigation",
    "",
    `Run \`node "<device directory>/${DEVICE_HOME_ENTRIES.engine}/${ENGINE_FILES.launcher}" <verb> --<flag> <value>\`. Root: \`~/${DIRECTORY.device}\` or \`${DEVICE_HOME_ENVIRONMENT_VARIABLE}\`; missing engine means install first. \`commands\` / \`<verb> --help\`: verbs/flags. Use current UTC \`--at\` and \`--workspace <library>\` as required. Closed inputs: actual engine bundle root \`specs/\` (beside \`scripts/\`), not this Skill.`,
    "",
    "Local sessions share queued writes without stepping aside, not cross-device exclusion. Remote submission needs serial handoff. No platform-native dot hook, background lifecycle manager or sync service is installed.",
    "",
    "| Moment | Verb | What to do |",
    "| --- | --- | --- |",
    ...SKILL_NAVIGATION.map(navigationRow),
    "",
    "## Three steps",
    "",
    "1. Install this skill: `npx skills add tpmoonchefryan/mana-orchestrate`.",
    `2. Say "install ${BRAND.engine.name}". Choose traditional hooks or independent dot target via \`setup\`; install.md guides approval.`,
    "3. Follow the navigation. Installation, policy changes, restoration and publication retain their separate approvals. 20-minute patrol and daily 00:00 Asia/Shanghai backup are independent; unapproved policy forbids daily enablement; unknown stays unknown.",
    "",
    "## Install-type tasks",
    "",
    "For install, restore, update, repair, rollback, migration, uninstall or health check, read `references/` (`install.md`, `restore.md`, `update.md`, `migrate.md`, `uninstall.md`, `doctor.md`); dot uses install; never load them for any other work.",
    "",
  ];
  const markdown = lines.join("\n");
  const bytes = Buffer.byteLength(markdown, "utf8");
  if (bytes >= SKILL_MARKDOWN_BYTE_LIMIT) {
    fail("SKILL_MARKDOWN_TOO_LARGE", `SKILL.md would be ${bytes} bytes; it must stay under ${SKILL_MARKDOWN_BYTE_LIMIT}`, { bytes: String(bytes), limit: String(SKILL_MARKDOWN_BYTE_LIMIT) });
  }
  return markdown;
}

/** Install-time compatibility check, not a runtime prerequisite for native tools. */
export const HOST_SKILL_PROTOCOL_MARKER = "Execution protocol: tcrn.host-execution-request.v1.";
export function checkHostSkillCompatibility(markdown: string, commandNames: readonly string[]): { readonly compatible: boolean; readonly missing: readonly string[]; readonly protocol: "host-native-v1" | "legacy" } {
  if (!markdown.includes(HOST_SKILL_PROTOCOL_MARKER)) return { compatible: true, missing: [], protocol: "legacy" };
  const missing = ["execution-host-prepare", "execution-host-record", "execution-host-evidence"].filter(name => !commandNames.includes(name));
  return { compatible: missing.length === 0, missing, protocol: "host-native-v1" };
}
